// Helpers for the r* (second) ENG-1955 verification pass. Reuses common.mjs editor finder.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { installEditorFinder, closeRoamDialogs, openPage, uidOf } from "./common.mjs";

export { installEditorFinder, closeRoamDialogs, openPage, uidOf };
const DIR = path.dirname(fileURLToPath(import.meta.url));
export const STATE2 = path.join(DIR, "state2.json");
export const readState2 = () => (fs.existsSync(STATE2) ? JSON.parse(fs.readFileSync(STATE2, "utf8")) : { pages: {}, createdPages: [] });
export const writeState2 = (s) => fs.writeFileSync(STATE2, JSON.stringify(s, null, 2));

export const REL = { supports: "2CcUT958c", opposes: "HoZktk5F4", corroborates: "en2037rel", informsCQ: "yd7pX2bvn" };
export const NODE = { claim: "eXm8WyS02", question: "WwAi4HfE0", evidence: "-YVlXUsDF" };

export const sleep = (page, ms) => page.waitForTimeout(ms);

// Writes partial results so a thrown step still leaves evidence on disk.
export const recorder = (outDir) => {
  const out = {};
  const flush = () => fs.writeFileSync(path.join(outDir, "result.json"), JSON.stringify(out, null, 2));
  const step = async (name, fn) => {
    try { out[name] = await fn(); } catch (e) { out[name] = { error: String(e?.message || e).slice(0, 400) }; }
    flush();
    return out[name];
  };
  return { out, step, flush };
};

export const allLogs = (page) => {
  const logs = [];
  page.on("console", (m) => logs.push({ t: Date.now(), type: m.type(), text: m.text().slice(0, 400) }));
  page.on("pageerror", (e) => logs.push({ t: Date.now(), type: "pageerror", text: String(e?.message || e).slice(0, 400) }));
  return logs;
};
export const errorsIn = (logs, from = 0) => logs.slice(from).filter((l) => ["error", "pageerror", "warning"].includes(l.type)).map((l) => `[${l.type}] ${l.text.split("\n")[0].slice(0, 200)}`);
export const maxDepth = (logs) => logs.filter((l) => /Maximum (store )?update depth/i.test(l.text)).length;

export const createPages = async (page, titles) => {
  const s = readState2();
  const uids = {};
  for (const [k, t] of Object.entries(titles)) {
    await page.evaluate((title) => window.roamAlphaAPI.data.page.create({ page: { title } }), t);
  }
  await sleep(page, 1500);
  for (const [k, t] of Object.entries(titles)) uids[k] = await uidOf(page, t);
  Object.assign(s.pages, Object.fromEntries(Object.entries(titles).map(([k, t]) => [k, { title: t, uid: uids[k] }])));
  s.createdPages = [...new Set([...(s.createdPages || []), ...Object.values(uids)])];
  writeState2(s);
  return uids;
};

export const waitCanvas = async (page, title, minShapes = 0, timeout = 60000) => {
  const start = Date.now();
  while (Date.now() - start < timeout) {
    const ok = await page.evaluate(({ t, n }) => {
      const ed = window.__eng1955Ed?.();
      return Boolean(ed) && document.querySelector(".rm-title-display")?.innerText.trim() === t && ed.getCurrentPageShapes().length >= n;
    }, { t: title, n: minShapes }).catch(() => false);
    if (ok) return true;
    await sleep(page, 300);
  }
  return false;
};

export const addNodes = (page, nodes) =>
  page.evaluate((nodes) => {
    const ed = window.__eng1955Ed();
    ed.createShapes(nodes.map((n) => ({ id: n.id, type: "discourse-node", x: n.x, y: n.y, props: { uid: n.uid, title: n.title, nodeTypeId: n.nodeTypeId, w: 220, h: 90 } })));
    return true;
  }, nodes);

export const zoomFit = async (page) => { await page.evaluate(() => { window.__eng1955Ed().zoomToFit(); return true; }); await sleep(page, 700); };

// Viewport (client) coordinates of a shape's page-bounds centre.
export const shapeCenter = (page, id) =>
  page.evaluate((id) => {
    const ed = window.__eng1955Ed();
    const b = ed.getShapePageBounds(id);
    if (!b) return null;
    const p = ed.pageToScreen({ x: b.midX, y: b.midY });
    return { x: p.x, y: p.y };
  }, id);

export const mouseDrag = async (page, from, to, steps = 12) => {
  await page.mouse.move(from.x, from.y);
  await page.mouse.down();
  for (let i = 1; i <= steps; i += 1) {
    await page.mouse.move(from.x + ((to.x - from.x) * i) / steps, from.y + ((to.y - from.y) * i) / steps);
    await sleep(page, 25);
  }
  await page.mouse.up();
};

export const relationShapes = (page) =>
  page.evaluate(() => {
    const ed = window.__eng1955Ed();
    const recs = ed.store.allRecords();
    const nodeUtil = (s) => s.type === "discourse-node" || Boolean(s.props?.nodeTypeId);
    const shapes = recs.filter((r) => r.typeName === "shape");
    const bindings = recs.filter((r) => r.typeName === "binding");
    return shapes.filter((s) => !nodeUtil(s)).map((s) => {
      const bs = bindings.filter((b) => b.fromId === s.id);
      const end = (t) => bs.find((b) => b.props?.terminal === t);
      return {
        id: s.id, type: s.type, index: s.index, parentId: s.parentId,
        relationTypeId: s.props?.relationTypeId, text: s.props?.text, color: s.props?.color, labelColor: s.props?.labelColor,
        bindingTypes: bs.map((b) => b.type), start: end("start")?.toId, end: end("end")?.toId,
      };
    });
  });

export const nodeShapes = (page) =>
  page.evaluate(() => window.__eng1955Ed().getCurrentPageShapes().filter((s) => s.type === "discourse-node").map((s) => ({ id: s.id, uid: s.props.uid, index: s.index, x: Math.round(s.x), y: Math.round(s.y) })));

// Stored (reified) relation blocks touching any of the given node uids.
export const storedRelations = (page, uids) =>
  page.evaluate(async (uids) => {
    const rows = await window.roamAlphaAPI.data.async.q(`[:find ?u ?d :where [?s :block/uid ?u] [?s :block/props ?p] [(get ?p :discourse-graph) ?d]]`);
    const g = (o, k) => o?.[`:${k}`] ?? o?.[k];
    return rows
      .map(([u, d]) => ({ uid: u, sourceUid: g(d, "sourceUid"), destinationUid: g(d, "destinationUid"), hasSchema: g(d, "hasSchema") }))
      .filter((r) => uids.includes(r.sourceUid) || uids.includes(r.destinationUid));
  }, uids);

// Pages created by the non-stored (triples) persistence path.
export const autoGeneratedPages = (page) =>
  page.evaluate(() => window.roamAlphaAPI.q(`[:find ?u ?t :where [?p :node/title ?t] [?p :block/uid ?u] [(clojure.string/includes? ?t "eng1955r")] [(clojure.string/starts-with? ?t "Auto generated from")]]`));

export const openSettings = async (page) => {
  await page.keyboard.press("Meta+p");
  await sleep(page, 700);
  await page.keyboard.type("DG: Open - Discourse settings");
  await sleep(page, 700);
  await page.keyboard.press("Enter");
  await page.locator("label.bp3-checkbox", { hasText: "Auto canvas relations" }).first().waitFor({ state: "visible", timeout: 15000 });
};
export const readAutoCanvasUI = async (page) => {
  await openSettings(page);
  const v = await page.locator("label.bp3-checkbox", { hasText: "Auto canvas relations" }).first().locator("input").isChecked();
  await closeRoamDialogs(page);
  return v;
};
export const setAutoCanvasUI = async (page, want) => {
  await openSettings(page);
  const label = page.locator("label.bp3-checkbox", { hasText: "Auto canvas relations" }).first();
  const cur = await label.locator("input").isChecked();
  if (cur !== want) await label.click();
  await sleep(page, 1200);
  const after = await label.locator("input").isChecked();
  await closeRoamDialogs(page);
  return { before: cur, after };
};

export const deleteOurPages = async (page) => {
  const s = readState2();
  const res = {};
  for (const uid of [...new Set(s.createdPages || [])]) {
    res[uid] = await page.evaluate(async (u) => {
      const title = window.roamAlphaAPI.pull("[:node/title]", [":block/uid", u])?.[":node/title"];
      if (!title) return "absent";
      if (!/eng1955r/.test(title)) return "skipped-not-ours";
      await window.roamAlphaAPI.data.page.delete({ page: { uid: u } });
      return "deleted";
    }, uid);
  }
  return res;
};
