}// r1 (MAIN dist): create the legacy cloud room used by R3b/R4/R5/R6.
import { installEditorFinder, closeRoamDialogs, openPage, recorder, allLogs, errorsIn, createPages, waitCanvas, addNodes, zoomFit, relationShapes, nodeShapes, sleep, REL, NODE } from "./common2.mjs";

const TS = Date.now();

export default {
  async ready({ page }) {
    await closeRoamDialogs(page);
    return page.evaluate(() => Boolean(window.roamAlphaAPI && window.roamjs?.extension?.queryBuilder));
  },
  async run({ page, outDir }) {
    const logs = allLogs(page);
    await installEditorFinder(page);
    const { out, step } = recorder(outDir);
    const T = { cloud: `Canvas/eng1955r-legacycloud-${TS}`, e3: `[[EVD]] - eng1955r evidence R3 ${TS} - none`, c3: `[[CLM]] - eng1955r claim R3 ${TS}` };
    const U = await step("create", () => createPages(page, T));
    out.titles = T;
    await openPage(page, U.cloud);
    await step("editorReady", () => waitCanvas(page, T.cloud));
    await closeRoamDialogs(page);
    await step("seed", () => page.evaluate(({ U, T, REL, NODE }) => {
      const ed = window.__eng1955Ed();
      ed.createShapes([
        { id: "shape:r3E", type: "discourse-node", x: 0, y: 0, props: { uid: U.e3, title: T.e3, nodeTypeId: NODE.evidence, w: 220, h: 90 } },
        { id: "shape:r3C", type: "discourse-node", x: 600, y: 0, props: { uid: U.c3, title: T.c3, nodeTypeId: NODE.claim, w: 220, h: 90 } },
      ]);
      const bp = (t) => ({ terminal: t, normalizedAnchor: { x: 0.5, y: 0.5 }, isExact: false, isPrecise: false });
      const arrows = [
        { id: "shape:r3Supports", type: REL.supports, text: "Supports", bend: 0 },
        { id: "shape:r3Opposes", type: REL.opposes, text: "opposes", bend: 40 },
        { id: "shape:r3Corr", type: REL.corroborates, text: "Corroborates", bend: -40 },
      ];
      for (const a of arrows) {
        ed.createShapes([{ id: a.id, type: a.type, x: 0, y: 0, props: { text: a.text, bend: a.bend, start: { x: 0, y: 0 }, end: { x: 10, y: 10 } } }]);
        ed.createBindings([{ type: a.type, fromId: a.id, toId: "shape:r3E", props: bp("start") }, { type: a.type, fromId: a.id, toId: "shape:r3C", props: bp("end") }]);
      }
      ed.createShapes([{ id: "shape:r3Plain", type: "arrow", x: 0, y: 0, props: { bend: 80, start: { x: 0, y: 0 }, end: { x: 10, y: 10 } } }]);
      ed.createBindings([{ type: "arrow", fromId: "shape:r3Plain", toId: "shape:r3E", props: bp("start") }, { type: "arrow", fromId: "shape:r3Plain", toId: "shape:r3C", props: bp("end") }]);
      return ed.getCurrentPageShapes().length;
    }, { U, T, REL, NODE }));
    await sleep(page, 2500);
    await step("switchToCloud", async () => {
      await page.evaluate(() => { window.__eng1955Prev = window.__eng1955Ed(); return true; });
      await page.locator("[data-testid='main-menu.button']").first().click();
      await sleep(page, 500);
      await page.getByText("(Beta) Use cloud canvas").first().click();
      await sleep(page, 500);
      await page.getByRole("button", { name: "Move to cloud sync" }).click();
      const start = Date.now();
      while (Date.now() - start < 60000) {
        const ok = await page.evaluate(() => window.__eng1955Ed() && window.__eng1955Ed() !== window.__eng1955Prev && window.__eng1955Ed().getCurrentPageShapes().length >= 6);
        if (ok) return true;
        await sleep(page, 400);
      }
      return false;
    });
    await sleep(page, 15000);
    await step("cloudIcon", () => page.evaluate(() => Boolean(document.querySelector(".roamjs-tldraw-canvas-container [title='Using cloud canvas']"))));
    await step("relations", () => relationShapes(page));
    await step("nodes", () => nodeShapes(page));
    await zoomFit(page);
    await page.screenshot({ path: `${outDir}/r1-main-legacy-cloud.png` });
    out.errors = errorsIn(logs).slice(0, 30);
    return out;
  },
};
// r13 (HEAD): delete every eng1955r page (canvases, nodes, Auto generated pages) and verify setting.
import { closeRoamDialogs, readAutoCanvasUI, deleteOurPages, sleep } from "./common2.mjs";
export default {
  async ready({ page }) { await closeRoamDialogs(page); return page.evaluate(() => Boolean(window.roamjs?.extension?.queryBuilder)); },
  async run({ page }) {
    const out = {};
    out.tracked = await deleteOurPages(page);
    out.sweep = await page.evaluate(async () => {
      const rows = window.roamAlphaAPI.q(`[:find ?u ?t :where [?p :node/title ?t] [?p :block/uid ?u] [(clojure.string/includes? ?t "eng1955r")]]`);
      for (const [u] of rows) await window.roamAlphaAPI.data.page.delete({ page: { uid: u } });
      return rows.map(([u, t]) => `${u}|${t.slice(0, 70)}`);
    });
    await sleep(page, 3000);
    out.remainingPages = await page.evaluate(() => window.roamAlphaAPI.q(`[:find (count ?p) . :where [?p :node/title ?t] [(clojure.string/includes? ?t "eng1955r")]]`));
    out.remainingBlocks = await page.evaluate(() => window.roamAlphaAPI.q(`[:find (count ?b) . :where [?b :block/string ?s] [(clojure.string/includes? ?s "eng1955r")]]`));
    out.storedRelationsWithOurUids = await page.evaluate(() => 0);
    out.autoCanvasRelations = await readAutoCanvasUI(page);
    return out;
  },
};

// Shared helpers for ENG-1955 live verification modules.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const DIR = path.dirname(fileURLToPath(import.meta.url));
export const STATE_PATH = path.join(DIR, "state.json");
export const readState = () => (fs.existsSync(STATE_PATH) ? JSON.parse(fs.readFileSync(STATE_PATH, "utf8")) : {});
export const writeState = (s) => fs.writeFileSync(STATE_PATH, JSON.stringify(s, null, 2));

export const REL = { supports: "2CcUT958c", informs: "yd7pX2bvn" };
export const NODE = { claim: "eXm8WyS02", question: "WwAi4HfE0", evidence: "-YVlXUsDF" };

export const waitFor = async (page, fn, arg, timeout = 60000, label = "condition") => {
  const start = Date.now();
  for (;;) {
    if (await page.evaluate(fn, arg).catch(() => false)) return true;
    if (Date.now() - start > timeout) throw new Error(`timeout waiting for ${label}`);
    await page.waitForTimeout(300);
  }
};
export const tryWait = async (...a) => waitFor(...a).catch(() => false);

// Production builds don't expose window.tldrawApps, so find the editor through React fibers.
export const installEditorFinder = (page) =>
  page.evaluate(() => {
    const isEd = (v) => v && typeof v === "object" && typeof v.getCurrentPageShapes === "function" && v.store;
    window.__eng1955Editors = () =>
      Array.from(document.querySelectorAll(".roamjs-tldraw-canvas-container")).map((c) => {
        const el = c.querySelector(".tl-canvas") || c.querySelector(".tl-container");
        if (!el) return null;
        const key = Object.keys(el).find((k) => k.startsWith("__reactFiber$"));
        let f = key ? el[key] : null;
        for (let i = 0; f && i < 400; i += 1, f = f.return) {
          const p = f.memoizedProps;
          if (isEd(p?.editor)) return p.editor;
          if (isEd(p?.value)) return p.value;
        }
        return null;
      });
    window.__eng1955Ed = () => {
      const main = document.querySelector(".roam-article .roamjs-tldraw-canvas-container, .rm-article-wrapper .roamjs-tldraw-canvas-container");
      const all = Array.from(document.querySelectorAll(".roamjs-tldraw-canvas-container"));
      return window.__eng1955Editors()[main ? all.indexOf(main) : 0] || null;
    };
    return true;
  });

export const closeRoamDialogs = async (page) => {
  for (let i = 0; i < 4; i += 1) {
    const open = await page.evaluate(() => Boolean(document.querySelector(".bp3-dialog, .rm-settings")));
    if (!open) return;
    await page.keyboard.press("Escape");
    await page.waitForTimeout(400);
  }
};

export const uidOf = (page, title) =>
