  const n = await handles.count();
  if (!n) return { error: "no handles", selected: await page.evaluate(() => window.__eng1955Ed().getSelectedShapeIds()) };
  const t = await shapeCenter(page, toId);
  let best = null; let bestD = Infinity;
  for (let i = 0; i < n; i += 1) {
    const b = await handles.nth(i).boundingBox();
    const d = b ? Math.hypot(b.x - t.x, b.y - t.y) : Infinity;
    if (d < bestD) { best = b; bestD = d; }
  }
  await mouseDrag(page, { x: best.x + best.width / 2, y: best.y + best.height / 2 }, t, 15);
  await sleep(page, 700);
  const options = await page.locator(".roamjs-tldraw-canvas-container button").filter({ has: page.locator("span.rounded-full") }).allInnerTexts();
  await page.locator(".roamjs-tldraw-canvas-container button", { hasText: new RegExp(`^${label}$`) }).first().click();
  await sleep(page, 4000);
  return { options };
};

