      const settingsUid = window.roamAlphaAPI.q(`[:find ?u . :where [?p :node/title "roam/js/discourse-graph"] [?p :block/uid ?u]]`);
      const tree = settingsUid ? window.roamAlphaAPI.pull("[:block/string :block/uid {:block/children ...}]", [":block/uid", settingsUid]) : null;
      const find = (arr, re) => (arr || []).find((c) => re.test(c[":block/string"] || ""));
      const grammar = find(tree?.[":block/children"], /^grammar$/i);
      const relNode = find(grammar?.[":block/children"], /^relations$/i);
      const rels = (relNode?.[":block/children"] || []).map((r) => {
        const kids = r[":block/children"] || [];
        const v = (k) => find(kids, new RegExp(`^${k}$`, "i"))?.[":block/children"]?.[0]?.[":block/string"];
        return { id: r[":block/uid"], label: r[":block/string"], source: v("Source"), destination: v("Destination"), complement: v("Complement") };
      });
      const props = settingsUid ? window.roamAlphaAPI.pull("[:block/props]", [":block/uid", settingsUid]) : null;
      const counts = {};
      for (const n of nodes) {
        if (n.backedBy === "default") continue;
        const rows = window.roamAlphaAPI.q(`[:find ?u ?t :where [?p :node/title ?t] [?p :block/uid ?u] [(clojure.string/starts-with? ?t "[[${(n.format||'').match(/^\[\[(\w+)\]\]/)?.[1]||'@@@'}]]")]]`).slice(0, 3);
        counts[n.type] = rows.map(([u, t]) => ({ uid: u, title: t.slice(0, 50) }));
      }
      return { nodes, relCount: rels.length, rels, propsKeys: Object.keys(props?.[":block/props"] || {}), samples: counts };
    });
  },
};

